script.text:
			
function active$VoucherFilter$(sender) {

sender.add_onResponseComplete(on$Filter$ResponseComplete);

}
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var k = new Array();
			var g = f.grid, tu_ngay = $func.formatDateOrder(f.getItemValue('tu_ngay')), den_ngay = $func.formatDateOrder(f.getItemValue('den_ngay')); 
console.log('tu_ngay', tu_ngay);
console.log('tu_ngay',  den_ngay);
			Array.add(k, {Name: 'ngay_dat_cho', Opr: '>=', Value: tu_ngay, Type: 'DateTime', Ignore: false});			Array.add(k, {Name: 'ngay_dat_cho', Opr: '<=', Value: den_ngay, Type: 'DateTime', Ignore: false});
		console.log('k', k);
			g.set_externalKey(k);
			break;
		default:
			break;
	}
}
